-- SQLite rowid tables do not enforce NOT NULL for non-INTEGER PRIMARY KEY columns.
-- These guards restore PostgreSQL primary-key semantics without rebuilding populated tables.
PRAGMA foreign_keys=ON;
CREATE TRIGGER IF NOT EXISTS mklms_pk_guard_certificate_templates_id_insert BEFORE INSERT ON "certificate_templates" WHEN NEW."id" IS NULL BEGIN SELECT RAISE(ABORT,'primary key cannot be NULL'); END;
CREATE TRIGGER IF NOT EXISTS mklms_pk_guard_certificate_templates_id_update BEFORE UPDATE OF "id" ON "certificate_templates" WHEN NEW."id" IS NULL BEGIN SELECT RAISE(ABORT,'primary key cannot be NULL'); END;
